select bm_material_trace_history.*, bm_procedure.name as procedure_name, bm_procedure_step.name as procedure_step_name, bm_process.name as process_name from bm_material_trace_history left join bm_procedure on bm_material_trace_history.procedure_id = bm_procedure.id left join bm_procedure_step on bm_material_trace_history.procedure_step_id = bm_procedure_step.id left join bm_process on bm_material_trace_history.process_id = bm_process.id
bm_material_trace_history.is_deleted = 0
and 1 = -1
and bm_material_trace_history.material_id in
#{materialId}
and bm_material_trace_history.procedure_step_id in
#{procedureStepId}
and (bm_material_trace_history.product_plan_id in
#{productPlanId}
or bm_material_trace_history.source_product_plan_id in
#{productPlanId}
)
